param([string]$GameRoot='F:/SteamLibrary/steamapps/common/RimWorld',[switch]$Check)
# Replays source identity, ranges and selected original XML. Does not execute target code.
$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$base=Join-Path $root 'docs/research/rimworld/evidence'
$dllHash='eff7d97949f919fb2b151ebfb906e9be749b63410b7dbda78eeebb7972b245c3'
$engineHash='587a18e18e13acfc7fd8783a44c24c7da0781dadf6b9fb9dd5e2e38a9cdfae78'
function Digest([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function TextDigest([string]$s){[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($s))).ToLowerInvariant()}
function LF([string]$s){$s.Replace(([string][char]13+[char]10),[string][char]10)}
if((Digest (Join-Path $GameRoot 'Assembly-CSharp.dll')) -ne $dllHash){throw 'Game assembly changed'}
if((Digest (Join-Path $root '../../tools/ilspy/lib/netstandard2.0/ICSharpCode.Decompiler.dll')) -ne $engineHash){throw 'Decompiler changed'}
$groups=[Collections.Generic.HashSet[string]]::new()
function Source([string]$group,[string]$type,[int]$start,[int]$end){
 $m=Get-Content (Join-Path $base "$group-manifest.json") -Raw|ConvertFrom-Json
 if($m.source_sha256 -ne $dllHash -or $m.engine_sha256 -ne $engineHash){throw "Mismatched provenance: $group"}
 $entries=@($m.types|Where-Object type -eq $type)
 if($entries.Count -ne 1){throw "Unknown type: $group/$type"}
 $t=$entries[0];$file=Join-Path $root $t.local_file
 if((Digest $file) -ne $t.sha256){throw "Changed source: $file"}
 $lines=[IO.File]::ReadAllText($file).Split([char]10)
 if($lines.Length -ne $t.lines -or $start -lt 1 -or $end -lt $start -or $end -gt $t.lines){throw "Invalid source range: $group/$type"}
 [void]$groups.Add($group)
 [ordered]@{group=$group;type=$type;file=$t.local_file;sha256=$t.sha256;lines=@($start,$end);excerpt_sha256=(TextDigest ($lines[($start-1)..($end-1)] -join [char]10))}
}
$xmlSpecs=@(
 [ordered]@{id='PBX01';file='Data/Core/Defs/Misc/BillDefs/BillRepeatModeDefs.xml';xpath='/Defs/BillRepeatModeDef';count=3;fields=@('defName','label','listOrder')},
 [ordered]@{id='PBX02';file='Data/Core/Defs/Misc/BillDefs/BillStoreModeDefs.xml';xpath='/Defs/BillStoreModeDef';count=3;fields=@('defName','label','listOrder')},
 [ordered]@{id='PBX03';file='Data/Core/Defs/RecipeDefs/Recipes_Meals.xml';xpath='/Defs/RecipeDef[defName="CookMealSimple" or defName="CookMealSimpleBulk"]';count=2;fields=@('defName','label','products/MealSimple','unfinishedThingDef')},
 [ordered]@{id='PBX04';file='Data/Core/Defs/RecipeDefs/Recipes_Production.xml';xpath='/Defs/RecipeDef[@Name="MakeStoneBlocksBase" or defName="Make_StoneBlocksAny"]';count=2;fields=@('defName','label','workerCounterClass','targetCountAdjustment','specialProducts/li','unfinishedThingDef')}
)
$xml=@(foreach($spec in $xmlSpecs){
 $file=Join-Path $GameRoot $spec.file
 [xml]$doc=[IO.File]::ReadAllText($file)
 $nodes=@(foreach($n in $doc.SelectNodes($spec.xpath)){
  $fields=[ordered]@{}
  foreach($p in $spec.fields){$f=$n.SelectSingleNode($p);if($f){$fields[$p]=$f.InnerText}}
  [ordered]@{name=$n.GetAttribute('Name');parent=$n.GetAttribute('ParentName');abstract=$n.GetAttribute('Abstract');fields=$fields}
 })
 if($nodes.Count -ne $spec.count){throw "Unexpected XML nodes: $($spec.id)"}
 [ordered]@{id=$spec.id;file=$spec.file;source_sha256=(Digest $file);xpath=$spec.xpath;projection='Selected fields and immediate inheritance only; not mod-patched effective Def data';nodes=$nodes;nodes_sha256=(TextDigest (LF ($nodes|ConvertTo-Json -Depth 8 -Compress)))}
})
$claims=@(
 [ordered]@{id='PB01';finding='Production bills support RepeatCount, Forever and TargetCount. Default constructor fields are RepeatCount, repeatCount1, targetCount10 and unpauseWhenYouHave5. Target mode selection checks recipe.WorkerCounter.CanCountProducts; the generic counter accepts one regular product and no specialProducts, while custom counters may override.';xml=@('PBX01');sources=@((Source 'stonecutting' 'RimWorld.Bill_Production' 10 40),(Source 'production-bills' 'RimWorld.BillRepeatModeUtility' 8 32),(Source 'stonecutting' 'Verse.RecipeWorkerCounter' 10 17))},
 [ordered]@{id='PB02';finding='RepeatCount measures completed recipe iterations, not individual output units. Notify_IterationCompleted decrements positive repeatCount and emits completion at zero without deleting the bill. Production generates all products, consumes ingredients, then calls that notification. Core CookMealSimpleBulk yields four meals per iteration.';xml=@('PBX03');sources=@((Source 'stonecutting' 'RimWorld.Bill_Production' 245 260),(Source 'food' 'Verse.AI.Toils_Recipe' 190 200),(Source 'production-bills' 'RimWorld.BillStack' 75 80))},
 [ordered]@{id='PB03';finding='ShouldDoNow clears automatic paused state outside TargetCount, rejects manual suspended, permits Forever, and permits RepeatCount only above zero. In TargetCount it sets paused at count>=target if pauseWhenSatisfied, clears paused at count<=unpauseWhenYouHave or when hysteresis is disabled, then requires !paused and count<target. Suspended returns before target reevaluation.';xml=@();sources=@((Source 'stonecutting' 'RimWorld.Bill_Production' 207 243))},
 [ordered]@{id='PB04';finding='The details UI exposes pauseWhenSatisfied and unpauseWhenYouHave only in TargetCount, nudges the resume threshold by target changes, and clamps a resume value >=target to target-1. Automatic paused and manual suspended are distinct. The status Unpause action clears paused; subsequent ShouldDoNow can pause again if count still reaches target. Raw target0 may produce resume-1 in this UI path; do not infer a universal nonnegative invariant.';xml=@();sources=@((Source 'production-bills' 'RimWorld.Dialog_BillConfig' 149 151),(Source 'production-bills' 'RimWorld.Dialog_BillConfig' 200 212),(Source 'stonecutting' 'RimWorld.Bill_Production' 329 344),(Source 'food' 'RimWorld.Bill' 370 376))},
 [ordered]@{id='PB05';finding='BillStack is an ordered list. Add appends and assigns stack; Reorder removes/reinserts the same bill. The listing offers Add while Count<15 and bill UI exposes bounded up/down actions. AddBill itself does not enforce MaxCount and Reorder itself does not guard excessive positive offsets; the observed cap/bounds belong to player UI.';xml=@();sources=@((Source 'production-bills' 'RimWorld.BillStack' 13 27),(Source 'production-bills' 'RimWorld.BillStack' 69 96),(Source 'production-bills' 'RimWorld.BillStack' 136 149),(Source 'food' 'RimWorld.Bill' 323 342))},
 [ordered]@{id='PB06';finding='WorkGiver_DoBill scans bills in list order, skips unsuitable work type, ingredient retry cooldown, ShouldDoNow false, pawn restrictions and recipe skill failures. Missing ingredients and a UFT bound to another worker also continue to later bills. It returns on a selected new/continuation job; a blocked first bill does not generally block the whole stack.';xml=@();sources=@((Source 'work' 'RimWorld.WorkGiver_DoBill' 189 238),(Source 'work' 'RimWorld.WorkGiver_DoBill' 261 296))},
 [ordered]@{id='PB07';finding='JobDriver_DoBill globally fails for deleted/dereferenced bill or unusable bill giver and reserves one bill giver. Manual suspended is separately a DoRecipeWork fail condition, so it interrupts the work stage; the inspected global condition has no suspended check during ingredient collection. Changing a bill is not equivalent to immediately cancelling every phase.';xml=@();sources=@((Source 'food' 'Verse.AI.JobDriver_DoBill' 54 113),(Source 'food' 'Verse.AI.Toils_Recipe' 153 165),(Source 'food' 'RimWorld.Bill' 111 125))},
 [ordered]@{id='PB08';finding='Reorder itself does not cancel the active job. The inspected ordinary work/finish toils do not recheck ShouldDoNow each work tick or trim the produced batch to the target. Thus target count is a scheduling threshold, not a hard output cap, and an in-flight batch can overshoot. Long UFT work explicitly checks job override after3000ticks on1000tick hash intervals, so absolute never-preempted semantics are not established.';xml=@('PBX03');sources=@((Source 'production-bills' 'RimWorld.BillStack' 87 96),(Source 'food' 'Verse.AI.Toils_Recipe' 90 165),(Source 'food' 'Verse.AI.Toils_Recipe' 170 200))},
 [ordered]@{id='PB09';finding='Default generic product counting uses ResourceCounter plus carried products only when CountAsResource, no equipped/include-group/material restriction and full quality/HP ranges (with the additional tainted-apparel condition). ResourceCounter enumerates held things of map slot groups, counts stacks of fresh/nonfogged resources, and refreshes periodically every204ticks. This fast path is not all loose objects anywhere on the map; it does not test forbidden or reachability.';xml=@();sources=@((Source 'stonecutting' 'Verse.RecipeWorkerCounter' 19 26),(Source 'stonecutting' 'RimWorld.ResourceCounter' 120 168))},
 [ordered]@{id='PB10';finding='Generic carried-product counting iterates spawned pawns in the player faction, checks carryTracker.CarriedThing after unwrapping minified content, and adds carried wrapper stackCount if valid. It is not all inventory and not just free colonists. The counter does not add promised output of active bills or unfinished-product ingredients.';xml=@();sources=@((Source 'stonecutting' 'Verse.RecipeWorkerCounter' 19 92),(Source 'stonecutting' 'Verse.RecipeWorkerCounter' 165 182),(Source 'food' 'Verse.AI.Toils_Recipe' 18 37))},
 [ordered]@{id='PB11';finding='The generic slow path without includeGroup scans map things of the product def, minified products, carried items and directly held things of haul sources. With includeGroup it enumerates that slot/group HeldThings. includeEquipped additionally scans free spawned colonists equipment, worn apparel and inventories even when includeGroup is selected. These scopes differ from the fast ResourceCounter path.';xml=@();sources=@((Source 'stonecutting' 'Verse.RecipeWorkerCounter' 27 92))},
 [ordered]@{id='PB12';finding='CountValidThing checks exact product def, tainted apparel, HP range, quality, allowed stuff when enabled, and fog; it does not check forbidden or path reachability. The List<Thing> CountValidThings overload increments one per valid object while the ThingOwner and slot paths sum stackCount. This derived asymmetry is retained as an unverified edge case, not assumed corrected or universally applied.';xml=@();sources=@((Source 'stonecutting' 'Verse.RecipeWorkerCounter' 94 149))},
 [ordered]@{id='PB13';finding='Make_StoneBlocksAny selects RecipeWorkerCounter_MakeStoneBlocks in Core XML. This custom CountProducts sums ResourceCounter across all StoneBlocks child defs, without calling the generic counter, adding carried count, or inspecting includeGroup/equipped/HP/quality/material flags. Its recipe target adjustment is20. Do not transfer this counting rule to individual-stone or other recipes without checking their worker counter.';xml=@('PBX04');sources=@((Source 'stonecutting' 'Verse.RecipeWorkerCounter_MakeStoneBlocks' 8 27))},
 [ordered]@{id='PB14';finding='Product-count includeGroup and product-delivery storeGroup are separate settings. Details UI offers include-from-all or a slot/group; output mode offers BestStockpile, SpecificStockpile or DropOnFloor. StorageGroup choices are deduplicated in the selector, and compatibility uses recipe.WorkerCounter.CanPossiblyStore. Invalid referenced output group causes DropOnFloor fallback; invalid includeGroup is cleared separately.';xml=@('PBX02');sources=@((Source 'stonecutting' 'RimWorld.Bill_Production' 176 205),(Source 'stonecutting' 'RimWorld.Bill_Production' 346 378),(Source 'production-bills' 'RimWorld.Dialog_BillConfig' 163 182),(Source 'production-bills' 'RimWorld.Dialog_BillConfig' 216 243),(Source 'production-bills' 'RimWorld.Dialog_BillConfig' 423 449),(Source 'production-bills' 'RimWorld.Dialog_BillConfig' 586 602))},
 [ordered]@{id='PB15';finding='After completion, DropOnFloor places all products near the actor. Other store modes drop all but the first product list entry, find ordinary or selected storage for the first, split excess carry capacity and start a real haul job; absent destination falls back to nearby placement. TargetCount completion refreshes ResourceCounter via a finish action. Storage choice neither teleports output nor creates a target-count reservation.';xml=@();sources=@((Source 'food' 'Verse.AI.Toils_Recipe' 170 179),(Source 'food' 'Verse.AI.Toils_Recipe' 222 297))},
 [ordered]@{id='PB16';finding='Recipes using UFT create a physical UnfinishedThing holding ingredients, creator, bill reference and workLeft. Work loads remaining work from initialized UFT and updates it during processing. Recipes without UFT initialize work from the full recipe when a fresh DoRecipeWork begins. Therefore resumption semantics depend on the recipe, not merely the existence of a bill.';xml=@();sources=@((Source 'food' 'Verse.AI.Toils_Recipe' 11 75),(Source 'food' 'Verse.AI.Toils_Recipe' 117 138),(Source 'weapons' 'Verse.UnfinishedThing' 138 151))},
 [ordered]@{id='PB17';finding='Bound UFT jobs are only returned for their bound worker when reachable/reservable/nonforbidden. Unbound search requires same recipe, same creator, currently allowed ingredients and reservation. Bill_ProductionWithUft can clear its binding when creator is downed/unspawned/destroyed/hosted or work disabled, but this does not prove another pawn can finish that old UFT: the search still checks Creator==pawn.';xml=@();sources=@((Source 'work' 'RimWorld.WorkGiver_DoBill' 162 185),(Source 'work' 'RimWorld.WorkGiver_DoBill' 223 238),(Source 'production-bills' 'RimWorld.Bill_ProductionWithUft' 22 55))},
 [ordered]@{id='PB18';finding='Delete marks the bill deleted, removes it from its stack, and invokes Notify_BillDeleted, which is empty in ordinary Building_WorkTable. UnfinishedThing lazily clears a deleted/dereferenced binding and saves its recipe/creator/ingredients/workLeft independently. Deleting a bill is therefore distinct from explicitly cancelling a physical UFT, whose Cancel destroy recovers a randomly rounded75percent of ingredients and clears binding.';xml=@();sources=@((Source 'production-bills' 'RimWorld.BillStack' 75 80),(Source 'stonecutting' 'RimWorld.Building_WorkTable' 116 118),(Source 'weapons' 'Verse.UnfinishedThing' 46 76),(Source 'weapons' 'Verse.UnfinishedThing' 138 170),(Source 'weapons' 'Verse.UnfinishedThing' 172 187))},
 [ordered]@{id='PB19';finding='BillStack serializes its ordered bill list deeply and restores each bill.stack reference. Bill persists loadID, recipe, manual suspended, ingredient filters and worker restrictions. Bill_Production persists repeat mode/count, target/resume/automatic paused, counting filters and output/include references. Bill_ProductionWithUft persists its bound UFT reference. Runtime roundtrip correctness remains a separate validation requirement.';xml=@();sources=@((Source 'production-bills' 'RimWorld.BillStack' 116 134),(Source 'food' 'RimWorld.Bill' 205 232),(Source 'stonecutting' 'RimWorld.Bill_Production' 113 149),(Source 'production-bills' 'RimWorld.Bill_ProductionWithUft' 95 105))},
 [ordered]@{id='PB20';finding='Bill UI exposes reorder/delete/copy/manual suspension and repeat controls. Switching mode via its menu changes mode alone; plus/minus on Forever instead switches to RepeatCount1. Production Clone carries repeat, target, counting/output filters and paused; its UFT subclass does not copy the bound unfinished item. Clipboard cloning does not imply a second physical in-progress product.';xml=@();sources=@((Source 'food' 'RimWorld.Bill' 323 376),(Source 'production-bills' 'RimWorld.BillRepeatModeUtility' 8 32),(Source 'stonecutting' 'RimWorld.Bill_Production' 281 326),(Source 'stonecutting' 'RimWorld.Bill_Production' 448 467),(Source 'production-bills' 'RimWorld.Bill_ProductionWithUft' 112 115))}
)
$reaFile=Join-Path $base 'production-bills-rea-managed.json'
$rea=Get-Content $reaFile -Raw|ConvertFrom-Json
if($rea.subject.digest.sha256 -ne $dllHash -or $rea.normalized_result.summary.module.mvid -ne '8e962ecc-7ac7-42d2-8f3b-1b16cd24d2cd'){throw 'REA identity mismatch'}
$manifestRecords=@(foreach($name in @($groups|Sort-Object)){[ordered]@{file="$name-manifest.json";sha256=(Digest (Join-Path $base "$name-manifest.json"))}})
$e=[ordered]@{
 evidence_id='RW17-PRODUCTION-BILLS';version_text=(Get-Content (Join-Path $GameRoot 'Version.txt') -Raw).Trim()
 source_sha256=$dllHash;engine_sha256=$engineHash;kind='Static derived reconstruction and selected Core XML; no target execution'
 rea=[ordered]@{file='production-bills-rea-managed.json';sha256=(Digest $reaFile);evidence_id=$rea.evidence_id;parent_evidence_id=$rea.normalized_result.parent_evidence_id;mvid=$rea.normalized_result.summary.module.mvid;metadata_coverage=$rea.normalized_result.summary.coverage.state}
 manifests=$manifestRecords;xml=$xml;claims=$claims
 limitations=@('Derived C# is not original source; unresolved dependencies are tolerated.','Core XML is not an evaluated mod/DLC Def database.','This collector does not run RimWorld or prove UI/runtime timing.','Suspension during collection, active-job reorder preemption, target changes mid-batch, UFT rebinding and save/load need dedicated runtime checks.','Generic slow-list stack counting, zero-target resume threshold and custom worker counters must not be generalized beyond the inspected paths.','REA target-framework metadata is preserved literally and is not a claim about the runtime used by the launched game.')
}
$text=(LF ($e|ConvertTo-Json -Depth 30))+[char]10
$output=Join-Path $base 'production-bills-evidence.json'
if($Check){if([IO.File]::ReadAllText($output) -cne $text){throw 'Retained production-bill evidence differs'};"Production-bill source/XML replay verified: $($claims.Count) claims"}
else{[IO.File]::WriteAllText($output,$text,[Text.UTF8Encoding]::new($false));"Collected $($claims.Count) production-bill claims"}
